Here is the root cause:
The bug was caused by the use of dynamically allocated base addresses in the test names logged by the `map_fixed_noreplace` test, leading to inconsistent test names between runs. This inconsistency made it difficult for CI systems to interpret and display results accurately, especially when different PAGE_SIZE configurations were involved.

Here is the patch:

 int main(void)
 {
 	unsigned long base_addr;
 	unsigned long flags, addr, size, page_size;
 	char *p;

 	ksft_print_header();
 	ksft_set_plan(9);

 	page_size = sysconf(_SC_PAGE_SIZE);

 	/* let's find a base addr that is free before we start the tests */
 	size = 5 * page_size;
 	base_addr = find_base_addr(size);

 	flags = MAP_PRIVATE | MAP_ANONYMOUS | MAP_FIXED_NOREPLACE;

 	/* Check we can map all the areas we need below */
 	addr = base_addr;
 	size = 5 * page_size;
 	p = mmap((void *)addr, size, PROT_NONE, flags, -1, 0);
 	if (p == MAP_FAILED) {
 		dump_maps();
 		ksft_exit_fail_msg("Error: couldn't map the space we need for the test\n");
 	}
 	if (munmap((void *)addr, 5 * page_size) != 0) {
 		dump_maps();
 		ksft_exit_fail_msg("Error: munmap failed!?\n");
 	}
-	ksft_test_result_pass("mmap() @ 0x%lx-0x%lx p=%p result=%m\n", addr, addr + size, p);
+	ksft_print_msg("mmap() @ 0x%lx-0x%lx p=%p result=%m\n", addr, addr + size, p);
+	ksft_test_result_pass("mmap() 5*PAGE_SIZE at base\n");

 	addr = base_addr + page_size;
 	size = 3 * page_size;
 	p = mmap((void *)addr, size, PROT_NONE, flags, -1, 0);
 	if (p == MAP_FAILED) {
 		dump_maps();
 		ksft_exit_fail_msg("Error: first mmap() failed unexpectedly\n");
 	}
-	ksft_test_result_pass("mmap() @ 0x%lx-0x%lx p=%p result=%m\n", addr, addr + size, p);
+	ksft_print_msg("mmap() @ 0x%lx-0x%lx p=%p result=%m\n", addr, addr + size, p);
+	ksft_test_result_pass("mmap() 3*PAGE_SIZE at base+PAGE_SIZE\n");

 	/*
 	 * Exact same mapping again:
 	 *   base |  free  | new
 	 *     +1 | mapped | new
 	 *     +2 | mapped | new
 	 *     +3 | mapped | new
 	 *     +4 |  free  | new
 	 */
 	addr = base_addr;
 	size = 5 * page_size;
 	p = mmap((void *)addr, size, PROT_NONE, flags, -1, 0);
 	if (p != MAP_FAILED) {
 		dump_maps();
 		ksft_exit_fail_msg("Error:1: mmap() succeeded when it shouldn't have\n");
 	}
-	ksft_test_result_pass("mmap() @ 0x%lx-0x%lx p=%p result=%m\n", addr, addr + size, p);
+	ksft_print_msg("mmap() @ 0x%lx-0x%lx p=%p result=%m\n", addr, addr + size, p);
+	ksft_test_result_pass("mmap() 5*PAGE_SIZE at base\n");

 	/*
 	 * Second mapping contained within first:
 	 *
 	 *   base |  free  |
 	 *     +1 | mapped |
 	 *     +2 | mapped | new
 	 *     +3 | mapped |
 	 *     +4 |  free  |
 	 */
 	addr = base_addr + (2 * page_size);
 	size = page_size;
 	p = mmap((void *)addr, size, PROT_NONE, flags, -1, 0);
 	if (p != MAP_FAILED) {
 		dump_maps();
 		ksft_exit_fail_msg("Error:2: mmap() succeeded when it shouldn't have\n");
 	}
-	ksft_test_result_pass("mmap() @ 0x%lx-0x%lx p=%p result=%m\n", addr, addr + size, p);
+	ksft_print_msg("mmap() @ 0x%lx-0x%lx p=%p result=%m\n", addr, addr + size, p);
+	ksft_test_result_pass("mmap() 2*PAGE_SIZE at base+PAGE_SIZE\n");

 	/*
 	 * Overlap end of existing mapping:
 	 *   base |  free  |
 	 *     +1 | mapped |
 	 *     +2 | mapped |
 	 *     +3 | mapped | new
 	 *     +4 |  free  | new
 	 */
 	addr = base_addr + (3 * page_size);
 	size = 2 * page_size;
 	p = mmap((void *)addr, size, PROT_NONE, flags, -1, 0);
 	if (p != MAP_FAILED) {
 		dump_maps();
 		ksft_exit_fail_msg("Error:3: mmap() succeeded when it shouldn't have\n");
 	}
-	ksft_test_result_pass("mmap() @ 0x%lx-0x%lx p=%p result=%m\n", addr, addr + size, p);
+	ksft_print_msg("mmap() @ 0x%lx-0x%lx p=%p result=%m\n", addr, addr + size, p);
+	ksft_test_result_pass("mmap() 2*PAGE_SIZE  at base+(3*PAGE_SIZE)\n");

 	/*
 	 * Overlap start of existing mapping:
 	 *   base |  free  | new
 	 *     +1 | mapped | new
 	 *     +2 | mapped |
 	 *     +3 | mapped |
 	 *     +4 |  free  |
 	 */
 	addr = base_addr;
 	size = 2 * page_size;
 	p = mmap((void *)addr, size, PROT_NONE, flags, -1, 0);
 	if (p != MAP_FAILED) {
 		dump_maps();
 		ksft_exit_fail_msg("Error:4: mmap() succeeded when it shouldn't have\n");
 	}
-	ksft_test_result_pass("mmap() @ 0x%lx-0x%lx p=%p result=%m\n", addr, addr + size, p);
+	ksft_print_msg("mmap() @ 0x%lx-0x%lx p=%p result=%m\n", addr, addr + size, p);
+	ksft_test_result_pass("mmap() 2*PAGE_SIZE bytes at base\n");

 	/*
 	 * Adjacent to start of existing mapping:
 	 *   base |  free  | new
 	 *     +1 | mapped |
 	 *     +2 | mapped |
 	 *     +3 | mapped |
 	 *     +4 |  free  |
 	 */
 	addr = base_addr;
 	size = page_size;
 	p = mmap((void *)addr, size, PROT_NONE, flags, -1, 0);
 	if (p == MAP_FAILED) {
 		dump_maps();
 		ksft_exit_fail_msg("Error:5: mmap() failed when it shouldn't have\n");
 	}
-	ksft_test_result_pass("mmap() @ 0x%lx-0x%lx p=%p result=%m\n", addr, addr + size, p);
+	ksft_print_msg("mmap() @ 0x%lx-0x%lx p=%p result=%m\n", addr, addr + size, p);
+	ksft_test_result_pass("mmap() PAGE_SIZE at base\n");

 	/*
 	 * Adjacent to end of existing mapping:
 	 *   base |  free  |
 	 *     +1 | mapped |
 	 *     +2 | mapped |
 	 *     +3 | mapped |
 	 *     +4 |  free  |  new
 	 */
 	addr = base_addr + (4 * page_size);
 	size = page_size;
 	p = mmap((void *)addr, size, PROT_NONE, flags, -1, 0);
 	if (p == MAP_FAILED) {
 		dump_maps();
 		ksft_exit_fail_msg("Error:6: mmap() failed when it shouldn't have\n");
 	}
-	ksft_test_result_pass("mmap() @ 0x%lx-0x%lx p=%p result=%m\n", addr, addr + size, p);
+	ksft_print_msg("mmap() @ 0x%lx-0x%lx p=%p result=%m\n", addr, addr + size, p);
+	ksft_test_result_pass("mmap() PAGE_SIZE at base+(4*PAGE_SIZE)\n");

 	addr = base_addr;
 	size = 5 * page_size;
 	if (munmap((void *)addr, size) != 0) {
 		dump_maps();
 		ksft_exit_fail_msg("Error: munmap failed!?\n");
 	}
 	ksft_test_result_pass("Base Address unmap() successful\n");

 	ksft_finished();
 }
